-- Synthetic relational data for acceptance testing on a dedicated PostgreSQL 17.
CREATE TABLE customers (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 email text NOT NULL UNIQUE, profile jsonb NOT NULL
);
CREATE TABLE products (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 sku text NOT NULL UNIQUE, price numeric(12,2) NOT NULL CHECK(price>0)
);
CREATE TABLE orders (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 customer_id bigint NOT NULL REFERENCES customers(id),
 placed_at timestamptz NOT NULL, state text NOT NULL CHECK(state IN ('paid','shipped'))
);
CREATE TABLE order_items (
 order_id bigint NOT NULL REFERENCES orders(id),
 line_no int NOT NULL, product_id bigint NOT NULL REFERENCES products(id),
 quantity int NOT NULL CHECK(quantity>0), unit_price numeric(12,2) NOT NULL,
 PRIMARY KEY(order_id,line_no)
);
INSERT INTO customers(email,profile)
 SELECT 'customer-'||i||'@example.invalid', jsonb_build_object('region',CASE WHEN i%2=0 THEN 'TR' ELSE 'GB' END,'tier',i%4)
 FROM generate_series(1,10000) AS i;
INSERT INTO products(sku,price)
 SELECT 'SKU-'||i, (100+i*7)::numeric/10 FROM generate_series(1,500) AS i;
INSERT INTO orders(customer_id,placed_at,state)
 SELECT ((i-1)%10000)+1, timestamptz '2026-01-01 00:00:00+00'+i*interval '1 minute', CASE WHEN i%2=0 THEN 'paid' ELSE 'shipped' END
 FROM generate_series(1,25000) AS i;
INSERT INTO order_items(order_id,line_no,product_id,quantity,unit_price)
 SELECT o.id, l, p.id, l, p.price FROM orders o CROSS JOIN generate_series(1,4) l
 JOIN products p ON p.id=((o.id+l-1)%500)+1;
CREATE INDEX orders_customer_id_idx ON orders(customer_id);
CREATE INDEX customers_profile_idx ON customers USING gin(profile);
CREATE VIEW order_totals AS SELECT order_id,sum(quantity*unit_price)::numeric(16,2) AS total FROM order_items GROUP BY order_id;
CREATE FUNCTION order_total(target bigint) RETURNS numeric LANGUAGE sql STABLE AS $$
 SELECT total FROM order_totals WHERE order_id=target
$$;
ANALYZE;
